def digital_root_total(limit):
    """Sum of the digital roots (repeated digit sums) of 1..limit-1."""
    total = 0
    for n in range(1, limit):
        r = n
        while r >= 10:
            s = 0
            while r > 0:
                s += r % 10
                r = r // 10
            r = s
        total += r
    return total

